use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},fmt::Write};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-local-difference-basis");for(file,relocate)in[("input-pins.json",true),("input-pins-v2.json",false)]{let pins:BTreeMap<String,String>=serde_json::from_value(read(r.join(file))).unwrap();assert_eq!(pins.len(),if relocate{205}else{207});for(p,h)in pins{let at=if relocate&&p==r.join("probe.rs").to_str().unwrap(){r.join("probe-initial.rs")}else{p.into()};assert_eq!(hash(at),h);}}
let src=Path::new("/home/ubuntu/src/zk-tools/zopro/crates/zopro-core/src");let affine=fs::read_to_string(src.join("msm_affine.rs")).unwrap();let mut expected=String::new();for(a,b)in[("fn unsigned_digit(","fn msm_unsigned_raw"),("fn booth_digit(","fn window<")]{let start=affine.find(a).unwrap();let end=affine[start..].find(b).unwrap()+start;expected.push_str(&affine[start..end]);}let phi=fs::read_to_string(src.join("msm_affine/g2_phi.rs")).unwrap();expected.push_str(&phi[phi.find("const C1:").unwrap()..phi.find("use zopro_bn254::{Fq,").unwrap()]);assert_eq!(fs::read_to_string(r.join("native-helpers.rs")).unwrap(),expected);
assert_eq!(read(r.join("run-v2/result.json"))["status"],"complete");for step in["link","census"]{let p=r.join("run-v2").join(step);let e=read(p.join("exit.json"));assert_eq!(e["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{stream}.log"))),e[format!("{stream}_sha256")].as_str().unwrap());}}
let out=fs::read_to_string(r.join("run-v2/census/stdout.log")).unwrap();let rows=out.lines().filter_map(|l|l.strip_prefix("ROW ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(rows.len(),27);let synthetic:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SYNTHETIC ")).unwrap()).unwrap();assert_eq!(synthetic["variant_vectors"],168);assert_eq!(synthetic["independent_interval_field_checks"],336);let mut seen=BTreeSet::new();let mut cases=Vec::new();let mut ratios=vec![];for row in &rows{let shape=row["shape"].as_str().unwrap();let query=row["query"].as_str().unwrap();assert!(seen.insert((shape,query)));assert_eq!(row["raw_and_solver_image_solutions_equal"],true);let v=row["stats"]["variants"].as_array().unwrap();assert_eq!(v.len(),3);let base=v[0]["stats"]["formation_plus_contribution_proxy"].as_f64().unwrap();for (i,label)in["identity","pair2","binary8"].iter().enumerate(){let c=&v[i];assert_eq!(c["variant"],*label);assert_eq!(c["exact_inverse_check"],true);assert_eq!(c["independent_interval_weighted_field_checks"],2);assert_eq!(c["extra_key_point_count"],0);if i!=0{let ratio=c["stats"]["formation_plus_contribution_proxy"].as_f64().unwrap()/base;assert!(ratio>1.);ratios.push(ratio);}}cases.push(json!({"shape":shape,"query":query,"identity":v[0],"pair2":v[1],"binary8":v[2],"pair2_proxy_ratio":v[1]["stats"]["formation_plus_contribution_proxy"].as_f64().unwrap()/base,"binary8_proxy_ratio":v[2]["stats"]["formation_plus_contribution_proxy"].as_f64().unwrap()/base}));}
assert!(out.lines().last().unwrap().starts_with("COMPLETE "));let results=json!({"status":"closed_verified","cases":cases,"rows":rows,"synthetic":synthetic,"original_pins_rehashed_via_initial_probe":205,"corrected_pins_rehashed":207,"source_extracted_helper_blocks_exact":true,"raw_vs_cached_vector_agreements":9,"explicit_scalar_solves":18,"real_variant_vectors":81,"real_inverse_checks":81,"real_independent_interval_field_checks":162,"all_54_candidate_proxy_comparisons_worse":true,"minimum_proxy_ratio":ratios.iter().copied().reduce(f64::min).unwrap(),"maximum_proxy_ratio":ratios.iter().copied().reduce(f64::max).unwrap(),"new_sdk_proofs":0,"new_gnark_exports":0,"adopted":false,"goal_achieved":false,"accepted_170_source_files_unchanged":true,"decision":"Do not rewrite key points or benchmark these fixed adjacent layouts: every candidate increases the declared contribution/formation proxy; duplicate destruction often overwhelms any local cancellation. This rejects tested layouts on fixtures, not every possible basis change.","next":"Use actual compiled callers and accepted profiles to assess a structurally different arithmetic/dataflow design; do not reroll opposite/globalmodal/adjacentdifference/SRE/GLS/packedbucket/kernel-split variants unchanged."});fs::write(r.join("results.json"),serde_json::to_vec_pretty(&results).unwrap()).unwrap();
let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-local-difference-basis");fs::create_dir(report).unwrap();let mut s=String::from("# Lossless local difference-basis screen\n\nBoth fixed adjacent query-basis layouts increase the declared point-work proxy in every one of 27 query vectors across nine fixtures. Primary pair2 ratios are 1.008629 for A and 1.003781 for B; binary8 is 1.017848 and 1.006869. No key-point rewrite, curve prototype or latency trial follows. Production is unchanged.\n\nFor a pair, (P,Q) becomes (P+Q,Q), while (a,b) becomes (a,b-a). The number of stored points stays fixed and the identity holds for arbitrary inputs. A binary block of eight applies left-point addition and right-scalar subtraction at each power-of-two level. It can expose nearby equal values as zeros without an additional table. Unlike the [global modal-origin screen](../2026-10-26-modal-scalar-census/README.md), it does not rely on a nonzero globally dominant value.\n\nThe screen counts distinct scalars as well as zeros, reproduces the accepted grouping sample/population policy under assumed successful reservation, and uses source-extracted exact unsigned digits, Booth digits and G2 phi splitting. Width/cache choices use the accepted 32-worker defaults: eligible exclusive G2 uses phi12, eligible deferred G1 uses signed12, and generic paths use their unsigned cache policy. Raw K remains diagnostic rather than accepted folded K/Euler H. This is query-level dispatch modeling, not execution of the full Key proof dispatcher.\n\nThe proxy adds modeled grouping-formation additions to nonzero digit contributions. Contributions are counted before free bucket seeding; weighted reduction, exceptional handling, grouping/translation time, preparation, reservation failure and scheduling are excluded. The proxy is neither exact total curve additions nor a latency prediction. Every tested candidate increases it even before charging transform costs.\n\n| Shape | Query | Original nonzero classes | Pair2 classes | Binary8 classes | Pair2 proxy/original | Binary8 proxy/original |\n| --- | --- | ---: | ---: | ---: | ---: | ---: |\n");for c in results["cases"].as_array().unwrap(){writeln!(s,"| {} | {} | {} | {} | {} | {:.6} | {:.6} |",c["shape"].as_str().unwrap(),c["query"].as_str().unwrap(),c["identity"]["stats"]["distinct_nonzero"],c["pair2"]["stats"]["distinct_nonzero"],c["binary8"]["stats"]["distinct_nonzero"],c["pair2_proxy_ratio"].as_f64().unwrap(),c["binary8_proxy_ratio"].as_f64().unwrap()).unwrap();}
s.push_str("\nThe main problem is lost duplicate grouping. For example, 2x2 B has 28,852 distinct nonzero scalar values; pair differences produce 46,863, and binary8 produces 47,608. Adjacent values rarely match, so extra differences usually add distinct values instead of zeros. This rejects these two fixed layouts on the measured fixtures, not arbitrary circuit-informed basis changes or other inputs.\n\n## Validation\n\nAll 81 real variant vectors invert exactly back to original scalars and pass 162 independent weighted field functionals. Transformed point weights are independently reconstructed using subtree-interval prefix sums; the point-update algorithm is not executed by that oracle. Another 168 synthetic variant vectors cover 14 ragged lengths, zero/equal/opposite/random patterns and all three variants, with 168 inverse and 336 weighted field checks. These are scalar-algebra checks, not actual curve or proof tests. Nine raw/cached-image solver output comparisons agree, from 18 explicit scalar solves. Private scalars/witnesses/points/proofs are not exported.\n\nAn initial link failed because the copied phi helper retains pub(super), which cannot appear at crate root. Nesting the byte-identical helper text in a module and adding call wrappers repaired visibility before any census execution; arithmetic, protocol and models were unchanged. The failed source/receipt remain. All 205 original pins match with one exact initial-probe relocation, and all 207 corrected pins match. Extracted helper bodies match the pinned accepted files exactly.\n\nNo candidate point image, SDK proof, Gnark export, latency, minimum-RAM, physical-device or AWS result is claimed. Proposed same-count storage has no measured memory qualification. Accepted primary remains historically 8.594267 ms and merge54 178.891799 ms. [Accepted comparisons against every supplied M5 CPU and Metal reference](../2026-10-25-grouping-module/artifacts/perf/report.md) remain unchanged; all eight CPU 10× targets are unmet.\n\n[Protocol](artifacts/experiment.json), [full counts and closing audit](artifacts/results.json), [driver](artifacts/probe.rs), [extracted native helpers](artifacts/native-helpers.rs), [link repair](artifacts/link-repair.json), [workflow](artifacts/plan-v2.json), [input pins](artifacts/input-pins-v2.json).\n");fs::write(report.join("README.md"),s).unwrap();println!("CLOSED81variantvectors162real+336syntheticfieldchecks; all54candidateproxiesworse;205original207correctedpins; no keyprototype");}
